(window.__quranSurahs=window.__quranSurahs||{})[102]={"nomPhon":"At-Takaathur","versets":{"1":{"text":"La course aux richesses vous distrait,","arabe":"أَلْهَىٰكُمُ ٱلتَّكَاثُرُ"},"2":{"text":"jusqu'à ce que vous visitiez les tombes.","arabe":"حَتَّىٰ زُرْتُمُ ٱلْمَقَابِرَ"},"3":{"text":"Mais non! Vous saurez bientôt!","arabe":"كَلَّا سَوْفَ تَعْلَمُونَ"},"4":{"text":"(Encore une fois)! Vous saurez bientôt!","arabe":"ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ"},"5":{"text":"Sûrement! Si vous saviez de science certaine.","arabe":"كَلَّا لَوْ تَعْلَمُونَ عِلْمَ ٱلْيَقِينِ"},"6":{"text":"Vous verrez, certes, la Fournaise.","arabe":"لَتَرَوُنَّ ٱلْجَحِيمَ"},"7":{"text":"Puis, vous la verrez certes, avec l'œil de la certitude.","arabe":"ثُمَّ لَتَرَوُنَّهَا عَيْنَ ٱلْيَقِينِ"},"8":{"text":"Puis, assurément, vous serez interrogés, ce jour-là, sur les délices.","arabe":"ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ"}}};